import { useSelector } from "react-redux";

import toast from "react-hot-toast";

import Button from "../components/Button";

import { normalizeText } from "../utils/textUtils";

import "../styles/report.css";

export default function ReportPage({ setCurrentPage }) {
  // REDUX

  const results = useSelector((state) => state.excel.results);

  const secondSheetData = useSelector((state) => state.excel.secondSheetData);

  const startDate = useSelector((state) => state.excel.startDate);

  const endDate = useSelector((state) => state.excel.endDate);

  const employeeInput = useSelector((state) => state.excel.employeeInput);

  // FORMAT DATE

  const formatDate = (date) => {
    if (!date) return "";

    const d = new Date(date);

    const day = String(d.getDate()).padStart(2, "0");

    const month = String(d.getMonth() + 1).padStart(2, "0");

    const year = d.getFullYear();

    return `${day}/${month}/${year}`;
  };

  // EMPLOYEE ARRAY

  const employeeArray = employeeInput
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);

  // COPY DATE

  const handleCopyDate = async () => {
    const text = `Từ ngày ${formatDate(startDate)} đến ngày ${formatDate(endDate)}`;

    await navigator.clipboard.writeText(text);

    toast.success("Đã copy thời gian!");
  };

  // COPY EMPLOYEE

  const handleCopyEmployees = async () => {
    const text = employeeArray.join(", ");

    await navigator.clipboard.writeText(text);

    toast.success("Đã copy danh sách nhân viên!");
  };

  // HELPER GET VALUE

  const getValueByKeyword = (row, keyword) => {
    if (!row) return "";

    const foundKey = Object.keys(row).find((key) =>
      normalizeText(key).includes(normalizeText(keyword)),
    );

    return foundKey ? row[foundKey] : "";
  };

  // BUILD REPORT DATA

  const reportData = results.map((item, index) => {
    // MATCH SHEET 2 BY STT

    const matchedRow = secondSheetData.find(
      (sheet2Row) =>
        String(sheet2Row["STT"]).trim() === String(item["STT"]).trim(),
    );

    // VIOLATION

    const violationValue = normalizeText(
      getValueByKeyword(matchedRow, "XÁC ĐỊNH TÍNH VI PHẠM"),
    );

    return {
      stt: index + 1,

      chiNhanh: getValueByKeyword(matchedRow, "CHI NHÁNH"),

      tuyen: getValueByKeyword(matchedRow, "TUYẾN"),

      bks: getValueByKeyword(matchedRow, "BKS"),

      noiDungPhanAnh: item["Nội dung tiếp nhận Phản ánh"] || "",

      nhanVienBiPhanAnh: item["Tên nhân viên QLCL-DV"] || "",

      khongViPham: violationValue.includes("không vi phạm") ? "✓" : "",

      viPham:
        violationValue.includes("vi phạm") &&
        !violationValue.includes("không vi phạm")
          ? "✓"
          : "",
    };
  });

  con

  return (
    <div className="report-page">
      {/* HEADER */}

      <div className="report-header">
        <div>
          <h1>Báo cáo hỗ trợ trích xuất</h1>

          <Button
            className="back-button"
            onClick={() => setCurrentPage("home")}
          >
            ← Quay lại
          </Button>
        </div>

        <p>
          Tổng số phản ánh:
          <span>{reportData.length}</span>
        </p>
      </div>

      {/* FILTER INFO */}

      <div className="report-filter-info">
        {/* DATE */}

        <div className="report-info-card">
          <div className="info-header">
            <div className="info-title">📅 Khoảng thời gian</div>

            <button className="copy-button" onClick={handleCopyDate}>
              Copy
            </button>
          </div>

          <div className="info-content">
            Từ ngày {formatDate(startDate)} đến ngày {formatDate(endDate)}
          </div>
        </div>

        {/* EMPLOYEE */}

        <div className="report-info-card">
          <div className="info-header">
            <div className="info-title">👤 Nhân viên QLCL-DV</div>

            <button className="copy-button" onClick={handleCopyEmployees}>
              Copy
            </button>
          </div>

          <div className="employee-tags">
            {employeeArray.map((employee, index) => (
              <span key={index} className="employee-tag">
                {employee}
              </span>
            ))}
          </div>
        </div>
      </div>

      {/* TABLE */}

      <div className="report-table-wrapper">
        <table className="report-table">
          <thead>
            <tr>
              <th>STT</th>

              <th>CHI NHÁNH</th>

              <th>Tuyến</th>

              <th>BKS</th>

              <th>Nội dung phản ánh</th>

              <th>Nhân viên bị phản ánh</th>

              <th>Không vi phạm</th>

              <th>Vi phạm</th>
            </tr>
          </thead>

          <tbody>
            {reportData.map((item, index) => (
              <tr key={index}>
                {/* STT */}

                <td>{item.stt}</td>

                {/* CHI NHÁNH */}

                <td>{item.chiNhanh}</td>

                {/* TUYẾN */}

                <td>{item.tuyen}</td>

                {/* BKS */}

                <td>{item.bks}</td>

                {/* NỘI DUNG */}

                <td>{item.noiDungPhanAnh}</td>

                {/* NHÂN VIÊN */}

                <td>{item.nhanVienBiPhanAnh}</td>

                {/* KHÔNG VP */}

                <td>{item.khongViPham}</td>

                {/* VP */}

                <td>{item.viPham}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
